test('invoiceTotals works with real invoice from createInvoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  assert(totals.subtotal > 0);
  assert(totals.vat > 0);
  assert(totals.total > 0);
});

test('lineDiscount no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 5 };
  const discount = lineDiscount(line);
  const expected = 9000 * 0.05;
  assert.equal(discount, expected);
});

test('lineDiscount includes bulk discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  const subtotal = 10000;
  const expected = Math.round(subtotal * 0.025);
  assert.equal(discount, expected);
});

test('lineDiscount applies bulk discount after regular discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 5 };
  const discount = lineDiscount(line);
  const subtotal = 10000;
  const regularDiscount = subtotal * 0.05;
  const afterRegular = subtotal - regularDiscount;
  const bulkDiscount = Math.round(afterRegular * 0.025);
  const expected = regularDiscount + bulkDiscount;
  assert.equal(discount, expected);
});

test('lineDiscount bulk discount for exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  assert(discount > 0);
});

test('lineDiscount no bulk discount for 9 units', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount bulk discount with large quantity', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  const expected = Math.round(100000 * 0.025);
  assert.equal(discount, expected);
});

test('lineDiscount combines regular and bulk correctly', () => {
  const line = { qty: 20, unitPrice: 5000, discountPercent: 10 };
  const subtotal = 100000;
  const regularDiscount = subtotal * 0.1;
  const afterRegular = subtotal - regularDiscount;
  const bulkDiscount = Math.round(afterRegular * 0.025);
  const discount = lineDiscount(line);
  assert.equal(discount, regularDiscount + bulkDiscount);
});

test('lineDiscount never returns negative', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  assert(discount >= 0);
});

test('lineVat calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  const subtotal = 100000;
  const bulkDiscount = Math.round(subtotal * 0.025);
  const afterDiscount = subtotal - bulkDiscount;
  const expectedVat = Math.round(afterDiscount * 0.21);
  assert.equal(vat, expectedVat);
});

test('invoiceTotals includes bulk discount in total discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedDiscount = Math.round(50000 * 0.025);
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals with regular and bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 15, unitPrice: 10000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 150000;
  const regularDiscount = subtotal * 0.05;
  const afterRegular = subtotal - regularDiscount;
  const bulkDiscount = Math.round(afterRegular * 0.025);
  const totalDiscount = regularDiscount + bulkDiscount;
  assert.equal(totals.discount, totalDiscount);
});

test('invoiceTotals total formula with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 12, unitPrice: 8000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = totals.subtotal - totals.discount + totals.vat;
  assert.equal(totals.total, expected);
});

test('invoiceTotals no bulk discount for lines with qty < 10', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 10000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 90000 * 0.05;
  assert.equal(totals.discount, expected);
});

test('invoiceTotals multiple lines with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 },
      { qty: 20, unitPrice: 3000, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Discount = Math.round(50000 * 0.025);
  const line2Discount = Math.round(60000 * 0.025);
  const line3Discount = 0;
  const expected = line1Discount + line2Discount + line3Discount;
  assert.equal(totals.discount, expected);
});

test('lineDiscount with mixed tier and bulk discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 15 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  assert(totals.discount > 0);
});

test('bulk discount correctly rounds fractional cents', () => {
  const line = { qty: 10, unitPrice: 333, discountPercent: 0 };
  const discount = lineDiscount(line);
  assert.equal(Number.isInteger(discount), true);
  assert(discount > 0);
});

