test('lineDiscount no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 5 };
  const discount = lineDiscount(line);
  const expected = 9000 * 0.05;
  assert.equal(discount, expected);
});

test('lineDiscount includes bulk discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  const subtotal = 10000;
  const expected = Math.round(subtotal * 0.025);
  assert.equal(discount, expected);
});

test('lineDiscount applies bulk discount after regular discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 5 };
  const discount = lineDiscount(line);
  const subtotal = 10000;
  const regularDiscount = subtotal * 0.05;
  const afterRegular = subtotal - regularDiscount;
  const bulkDiscount = Math.round(afterRegular * 0.025);
  const expected = regularDiscount + bulkDiscount;
  assert.equal(discount, expected);
});

test('lineDiscount bulk discount for exactly 10 units', () => {
